#!/bin/sh
# Build the clean paper (paper.pdf) and the highlighted version (paper_changes.pdf).
# paper_changes.tex is GENERATED by latexdiff from ../submission1/paper.tex -> paper.tex;
# never edit it by hand. Additions/changes are blue, deletions are hidden.
set -e
cd "$(dirname "$0")"
latexmk -pdf -interaction=nonstopmode paper.tex > /dev/null
latexdiff --preamble=latexdiff_preamble.tex --math-markup=whole --graphics-markup=none \
    ../submission1/paper.tex paper.tex > paper_changes.tex 2> /dev/null
latexmk -pdf -interaction=nonstopmode paper_changes.tex > /dev/null
latexmk -c paper.tex paper_changes.tex > /dev/null
echo "Built paper.pdf and paper_changes.pdf"
